using UnityEngine; namespace Crownfall.Skills { [CreateAssetMenu(fileName="ShieldEffect",menuName="Crownfall/Skills/Effects/Shield")] public sealed class ShieldEffectDefinition:SkillEffectDefinition { public float targetMaxHealthPercent=.12f; public float duration=4; public override void Execute(SkillContext c,Crownfall.Units.Unit t){if(t!=null&&t.Team==c.Caster.Team)t.Shields.Add(t.Definition.maxHealth*targetMaxHealthPercent,duration);} } }
